def all_different(paquete):
    """ list -> bool """
    i = 1
    are_different = True
    while are_different and i<len(paquete):
        if paquete[i] in paquete[:i] + paquete[i+1:]:
            are_different = False
        i += 1
    return are_different

C024.solucion:
def extraer_sublista_es(lista_entregas):
    """ list -> list
        OBJ: Extrae una sublista con todas las entregas para España
    """
    lista_entregas_es = []
    for entrega in lista_entregas:
        if entrega['pais'] == 'ES':
            lista_entregas_es.append(entrega)
    return lista_entregas_es

def extraer_sublista_es_rec(lista_entregas):
    """ list -> list
        OBJ: Extrae recursivamente una sublista con todas las entregas para España
    """
    if lista_entregas == []: return []
    elif lista_entregas[0]['pais'] == 'ES':
        return [lista_entregas[0]] + extraer_sublista_es_rec(lista_entregas[1:])
    else: return extraer_sublista_es_rec(lista_entregas[1:])

