def clasificar_por_provincia(lista_entregas):
    """ list -> dict
        OBJ: Genera un diccionario donde se listan por código de provincia
             los regalos a entregar en esa zona.
    """
    entregas_por_provincia = {}
    for entrega in lista_entregas:
        cod_provincia = entrega['cod_postal'][:2]
        if cod_provincia not in entregas_por_provincia:
            entregas_por_provincia[cod_provincia] = entrega['lista_regalos']
        else:
            entregas_por_provincia[cod_provincia] += entrega['lista_regalos']
    return entregas_por_provincia
